/**
 * PostCSS Plugin to extract and track Tailwind CSS classes
 * This plugin captures all classes that Tailwind actually generates
 */
const fs = require('fs');
const path = require('path');

const tailwindClassExtractor = (opts = {}) => {
  return {
    postcssPlugin: 'tailwind-class-extractor',
    Once(root, helpers) {
      // Store for all generated Tailwind classes
      const generatedClasses = new Set();
      
      // Walk through all CSS rules generated by Tailwind
      root.walkRules(rule => {
        rule.selectors.forEach(selector => {
          // Extract class names from various selector formats
          const classMatches = selector.match(/\.([a-zA-Z0-9_-]+(?:\\:[a-zA-Z0-9_-]+)*)/g);
          
          if (classMatches) {
            classMatches.forEach(match => {
              // Remove the dot and unescape CSS class name
              let className = match.substring(1);
              
              // Convert escaped CSS format back to Tailwind format
              // hover\:bg-blue-700 becomes hover:bg-blue-700
              className = className.replace(/\\\\/g, '');
              
              // Only include classes that look like Tailwind utilities
              if (isTailwindUtilityClass(className)) {
                generatedClasses.add(className);
              }
            });
          }
        });
      });
      
      // Save generated classes to info file
      this.saveGeneratedClasses(Array.from(generatedClasses));
    },
    
    saveGeneratedClasses(classes) {
      try {
        const infoData = {
          generated_at: new Date().toISOString(),
          total_generated_classes: classes.length,
          generated_classes: classes.sort(),
          source: 'postcss-tailwind-extraction'
        };
        
        const outputPath = path.resolve('./tailwind-generated-classes.json');
        fs.writeFileSync(outputPath, JSON.stringify(infoData, null, 2));
        
        console.log(`✅ Tailwind Generated Classes: ${classes.length} classes captured`);
      } catch (error) {
        console.warn('Failed to save generated classes:', error.message);
      }
    }
  }
};

/**
 * Enhanced detection for Tailwind utility classes
 */
function isTailwindUtilityClass(className) {
  if (!className || typeof className !== 'string') return false;
  
  // Skip non-utility classes (components, etc.)
  const skipPatterns = [
    /^container$/,
    /^prose/,
    /^sr-only$/,
    /^not-sr-only$/
  ];
  
  if (skipPatterns.some(pattern => pattern.test(className))) {
    return true; // These are still Tailwind classes
  }
  
  // Tailwind utility class patterns
  const utilityPatterns = [
    // Responsive and state variants
    /^(sm|md|lg|xl|2xl):/,
    /^(hover|focus|active|disabled|visited|first|last|odd|even|group-hover|focus-within):/,
    /^(dark|light):/,
    
    // Layout utilities
    /^(block|inline|inline-block|flex|inline-flex|table|table-row|table-cell|grid|inline-grid|hidden)$/,
    /^(float|clear)-(left|right|none)$/,
    /^(object)-(contain|cover|fill|none|scale-down)$/,
    /^(overflow)-(auto|hidden|visible|scroll|x-auto|x-hidden|x-visible|x-scroll|y-auto|y-hidden|y-visible|y-scroll)$/,
    
    // Flexbox & Grid
    /^(flex|grid)-(row|col|flow)(-reverse)?$/,
    /^(justify|items|self|content)-(start|end|center|between|around|evenly|stretch|baseline|auto)$/,
    /^(flex)-(1|auto|initial|none|grow|shrink)(-\d+)?$/,
    /^(order)-(\d+|first|last|none)$/,
    /^(gap|row-gap|col-gap)(-\d+(\.\d+)?)?$/,
    
    // Spacing (padding, margin)
    /^[mp][trblxy]?(-\d+(\.\d+)?|auto)$/,
    /^space-[xy]-(\d+(\.\d+)?|reverse)$/,
    
    // Sizing
    /^(w|h|min-w|min-h|max-w|max-h)-(\d+(\.\d+)?|auto|full|screen|min|max|fit|px)$/,
    
    // Typography
    /^(text)-(xs|sm|base|lg|xl|2xl|3xl|4xl|5xl|6xl|7xl|8xl|9xl)$/,
    /^(text)-(left|center|right|justify|start|end)$/,
    /^(font)-(thin|extralight|light|normal|medium|semibold|bold|extrabold|black)$/,
    /^(font)-(sans|serif|mono)$/,
    /^(leading)-(none|tight|snug|normal|relaxed|loose|\d+)$/,
    /^(tracking)-(tighter|tight|normal|wide|wider|widest)$/,
    /^(text)-(inherit|current|transparent|black|white|slate|gray|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose)-(\d+)?$/,
    
    // Backgrounds
    /^(bg)-(inherit|current|transparent|black|white|slate|gray|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose)-(\d+)?$/,
    /^(bg)-(fixed|local|scroll)$/,
    /^(bg)-(auto|cover|contain)$/,
    /^(bg)-(bottom|center|left|left-bottom|left-top|right|right-bottom|right-top|top)$/,
    /^(bg)-(no-repeat|repeat|repeat-x|repeat-y|repeat-round|repeat-space)$/,
    
    // Borders
    /^(border)(-\d+)?$/,
    /^(border)-[trblxy](-\d+)?$/,
    /^(border)-(inherit|current|transparent|black|white|slate|gray|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose)-(\d+)?$/,
    /^(border)-(solid|dashed|dotted|double|hidden|none)$/,
    /^(rounded)(-none|-sm|-md|-lg|-xl|-2xl|-3xl|-full)?$/,
    /^(rounded)-(t|r|b|l|tl|tr|br|bl)(-none|-sm|-md|-lg|-xl|-2xl|-3xl|-full)?$/,
    
    // Effects
    /^(shadow)(-none|-sm|-md|-lg|-xl|-2xl|-inner)?$/,
    /^(opacity)-(\d+)$/,
    /^(blur|brightness|contrast|drop-shadow|grayscale|hue-rotate|invert|saturate|sepia)(-none|-sm|-md|-lg|-xl|-2xl|-3xl)?$/,
    
    // Filters
    /^(backdrop)-(blur|brightness|contrast|grayscale|hue-rotate|invert|opacity|saturate|sepia)(-none|-sm|-md|-lg|-xl|-2xl|-3xl)?$/,
    
    // Tables
    /^(border)-(collapse|separate)$/,
    /^(table)-(auto|fixed)$/,
    
    // Transitions & Animation
    /^(transition)(-none|-all|-colors|-opacity|-shadow|-transform)?$/,
    /^(duration)-(\d+)$/,
    /^(ease)-(linear|in|out|in-out)$/,
    /^(delay)-(\d+)$/,
    /^(animate)-(none|spin|ping|pulse|bounce)$/,
    
    // Transforms
    /^(transform)(-gpu|-none)?$/,
    /^(origin)-(center|top|top-right|right|bottom-right|bottom|bottom-left|left|top-left)$/,
    /^(scale|rotate|translate|skew)-[xy]?(-\d+)?$/,
    
    // Interactivity
    /^(appearance)-(none|auto)$/,
    /^(cursor)-(auto|default|pointer|wait|text|move|help|not-allowed|none|context-menu|progress|cell|crosshair|vertical-text|alias|copy|no-drop|grab|grabbing|all-scroll|col-resize|row-resize|n-resize|e-resize|s-resize|w-resize|ne-resize|nw-resize|se-resize|sw-resize|ew-resize|ns-resize|nesw-resize|nwse-resize|zoom-in|zoom-out)$/,
    /^(outline)(-none|-white|-black|\d+)?$/,
    /^(pointer-events)-(none|auto)$/,
    /^(resize)(-none|-y|-x)?$/,
    /^(select)-(none|text|all|auto)$/,
    /^(user-select)-(none|text|all|auto)$/,
    
    // SVG
    /^(fill)-(current|inherit|transparent|black|white|slate|gray|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose)-(\d+)?$/,
    /^(stroke)-(current|inherit|transparent|black|white|slate|gray|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose)-(\d+)?$/,
    /^(stroke)-(\d+)$/,
    
    // Accessibility
    /^(sr-only|not-sr-only)$/,
    
    // Position
    /^(static|fixed|absolute|relative|sticky)$/,
    /^(inset|top|right|bottom|left)-(\d+(\.\d+)?|auto|px)$/,
    /^(z)-(\d+|auto)$/
  ];
  
  return utilityPatterns.some(pattern => pattern.test(className));
}

tailwindClassExtractor.postcss = true;

module.exports = tailwindClassExtractor;